<template><section class="space-y-6"><header><p class="premium-kicker text-xs font-bold uppercase text-brand">Account</p><h1 class="premium-title mt-2 text-3xl font-800">Billing & folios</h1></header><div class="grid gap-5 lg:grid-cols-3"><article class="panel p-6"><p class="text-sm text-slate-500">Available folios</p><p class="mt-2 text-4xl font-800">{{ user.folioBalance || 0 }}</p><form class="mt-5 flex items-end gap-2" @submit.prevent="purchase"><label class="flex-1"><span class="mb-1 block text-xs font-bold">Folios to buy</span><input v-model.number="quantity" class="field" type="number" min="1" max="100" step="1" required></label><button class="btn-brand">Buy</button></form></article><article class="panel p-6 lg:col-span-2"><h2 class="font-800">Recent transactions</h2><div v-for="transaction in transactions" :key="transaction.id" class="mt-4 flex justify-between border-b border-slate-100 pb-3"><span><b>{{ transaction.description }}</b><small class="mt-1 block text-slate-500">{{ store.date(transaction.date) }}</small></span><b>{{ store.money(transaction.amount) }}</b></div><p v-if="!transactions.length" class="mt-5 text-slate-500">No billing activity.</p></article></div></section></template>
<script>
const { inject, computed, ref } = Vue;
export default { setup() { const store=inject('store'),user=store.currentUser,quantity=ref(10),transactions=computed(()=>store.state.transactions.filter(item=>item.userId===user.value.id)); function purchase(){const amount=Number(quantity.value);if(!Number.isInteger(amount)||amount<1||amount>100)return store.notice('Choose between 1 and 100 folios','fa-triangle-exclamation');user.value.folioBalance=(user.value.folioBalance||0)+amount;store.state.transactions.unshift({id:window.ProcurementCommon.uid('txn'),userId:user.value.id,type:'Folio purchase',amount:-amount*5,date:new Date().toISOString(),description:`Purchased ${amount} CFDI folios`});store.notice('Folios added')} return{store,user,quantity,transactions,purchase}; } };
</script>